export class ServiceApi {
    constructor(baseUrl) {
        this.baseUrl = baseUrl;
    }

    _request(endpoint, options = {}) {
        const url = `${this.baseUrl}${endpoint}`;
        const defaultHeaders = {
            'Content-Type': 'application/json',
        };
        const headers = { ...defaultHeaders, ...options.headers };
        const config = { ...options, headers };

        return fetch(url, config)
            .then(response => {
                if (!response.ok) {
                    return response.json().catch(() => ({})).then(errorData => {
                        throw new Error(errorData.message || `HTTP Error: ${response.status}`)
                    })
                }

                if (response.status === 204) return null;
                return response.json();
            });
    }

    getAll(endpoint, params = {}) {
        const queryString = new URLSearchParams(params).toString();
        const url = queryString ? `${endpoint}?${queryString}` : endpoint;

        return this._request(url, { method: 'GET' });
    }

    getById(endpoint, id) {
        return this._request(`${endpoint}/${id}`, { method: 'GET' });
    }

    create(endpoint, data) {
        return this._request(endpoint, {
            method: 'POST',
            body: JSON.stringify(data),
        });
    }

    update(endpoint, id, data, method = 'PATCH') {
        return this._request(`${endpoint}/${id}`, {
            method: method,
            body: JSON.stringify(data),
        });
    }

    delete(endpoint, id) {
        return this._request(`${endpoint}/${id}`, { method: 'DELETE' });
    }
}
